42	    /// <inheritdoc />
43	    public virtual IVectorStoreRecordCollection<TKey, TRecord> GetCollection<TKey, TRecord>(string name, VectorStoreRecordDefinition? vectorStoreRecordDefinition = null)
44	        where TKey : notnull
45	    {
46	#pragma warning disable CS0618 // ISqliteVectorStoreRecordCollectionFactory is obsolete
47	        if (this._options.VectorStoreCollectionFactory is not null)
48	        {
49	            return this._options.VectorStoreCollectionFactory.CreateVectorStoreRecordCollection<TKey, TRecord>(
50	                this._connection,
51	                name,
52	                vectorStoreRecordDefinition);
53	        }
54	#pragma warning restore CS0618
55	
56	        if (typeof(TKey) != typeof(string) && typeof(TKey) != typeof(ulong))
57	        {
58	            throw new NotSupportedException($"Only {nameof(String)} and {nameof(UInt64)} keys are supported.");
59	        }
60	
61	        var recordCollection = new SqliteVectorStoreRecordCollection<TRecord>(
62	            this._connection,
63	            name,
64	            new()
65	            {
66	                VectorStoreRecordDefinition = vectorStoreRecordDefinition,
67	                VectorSearchExtensionName = this._options.VectorSearchExtensionName,
68	                VectorVirtualTableName = this._options.VectorVirtualTableName
69	            }) as IVectorStoreRecordCollection<TKey, TRecord>;
70	
71	        return recordCollection!;
72	    }
