    /// <summary>
    /// Casts the provided <see cref="DbConnection"/> to <see cref="SqliteConnection"/>, which is required by the command builder.
    /// </summary>
    private static SqliteConnection GetSqliteConnection(DbConnection connection)
    {
        Verify.NotNull(connection);

        return connection as SqliteConnection
            ?? throw new ArgumentException($"The provided connection must be of type '{nameof(SqliteConnection)}'.", nameof(connection));
    }

    /// <summary>
    /// Ensures that the underlying connection is open. When the connection is owned by this instance, the connection is
    /// opened and the vector search extension is loaded, so that the library manages the connection lifecycle internally.
    /// </summary>
    private async Task EnsureConnectionOpenAsync(CancellationToken cancellationToken)
    {
        if (this._ownsConnection && this._connection.State != ConnectionState.Open)
        {
            await this._connection.OpenAsync(cancellationToken).ConfigureAwait(false);

            this._connection.LoadExtension(this._vectorSearchExtensionName);
        }
    }

    #endregion

    /// <inheritdoc />
    public void Dispose()
    {
        this.Dispose(true);
        GC.SuppressFinalize(this);
    }

    /// <summary>
    /// Disposes the resources used by this instance, disposing the underlying connection when it is owned by this instance.
    /// </summary>
    protected virtual void Dispose(bool disposing)
    {
        if (this._disposed)
        {
            return;
        }

        if (disposing && this._ownsConnection)
        {
            this._connection.Dispose();
        }

        this._disposed = true;
    }
